def pit_result(returned_earth):
    return {'SURPLUS':'FAT_SOIL','DEFICIT':'LEAN_SOIL','EQUAL_LEVEL':'MODERATE_SOIL'}[returned_earth]

def taste_result(sample_region, water, vessel):
    assert sample_region == 'PART_MOST_DISPLEASING'
    assert water == 'SWEET_WATER' and vessel == 'EARTHEN'
    return 'SWEETNESS_OBSERVED'

def parse(case):
    out = {'field':case['field'], 'region':case['region']}
    if case['method'] == 'PIT_REFILL':
        out['pit'] = case['pit']
        out['result'] = pit_result(case['returned_earth'])
    elif case['method'] == 'TASTE':
        out['sample'] = case['sample']
        out['result'] = taste_result(case['sample_region'], case['water'], case['vessel'])
    else:
        raise ValueError('unknown source method')
    return out

result = {
  'pit_surplus': parse({'field':'F1','region':'R1','method':'PIT_REFILL','pit':'P1','returned_earth':'SURPLUS'}),
  'pit_deficit': parse({'field':'F1','region':'R2','method':'PIT_REFILL','pit':'P2','returned_earth':'DEFICIT'}),
  'pit_equal': parse({'field':'F1','region':'R3','method':'PIT_REFILL','pit':'P3','returned_earth':'EQUAL_LEVEL'}),
  'worst_region_taste': parse({'field':'F1','region':'R4','method':'TASTE','sample':'CLOD4','sample_region':'PART_MOST_DISPLEASING','water':'SWEET_WATER','vessel':'EARTHEN'})
}
